#include <cstdio>
#include <cctype>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

typedef pair<int, int> point;

const int MAX_INF = 1000000000;
const int MAX_SIZE = 11;
const int MAX_NODES = 205;
const int DIRECTIONS = 4;
const int dy[DIRECTIONS] = {-1, 0, 1, 0};
const int dx[DIRECTIONS] = {0, -1, 0, 1};

int size_n, max_t;
char grid_map[MAX_SIZE][MAX_SIZE], backup_map[MAX_SIZE][MAX_SIZE];
int start_r, start_c;
int dist_bum[MAX_SIZE][MAX_SIZE];
int dist_map[MAX_SIZE][MAX_SIZE];
bool reachable_map[MAX_SIZE][MAX_SIZE];
int total_vertices;
int capacity[MAX_SIZE][MAX_SIZE];
vector<int> adjacency[MAX_NODES];
int flow_array[MAX_NODES], parent_array[MAX_NODES];

void first_bfs()
{
    fill((int*)capacity, (int*)capacity + MAX_SIZE * MAX_SIZE, max_t);
    capacity[start_r][start_c] = 0;
    queue<point> q; q.push(point(start_r, start_c));
    while (!q.empty()) {
        point v = q.front(); int d = capacity[v.first][v.second]; q.pop();
        for (int dir = 0; dir < DIRECTIONS; dir++) {
            point u = point(v.first + dy[dir], v.second + dx[dir]);
            if (0 <= u.first && u.first < size_n && 0 <= u.second && u.second < size_n && grid_map[u.first][u.second] != 'Y' && d + 1 < capacity[u.first][u.second])
                capacity[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void second_bfs(int sr, int sc)
{
    fill((int*)dist_map, (int*)dist_map + MAX_SIZE * MAX_SIZE, MAX_INF);
    dist_map[sr][sc] = 0;
    fill((bool*)reachable_map, (bool*)reachable_map + MAX_SIZE * MAX_SIZE, false);
    reachable_map[sr][sc] = true;
    queue<point> q; q.push(point(sr, sc));
    while (!q.empty()) {
        point v = q.front(); int d = dist_map[v.first][v.second]; q.pop();
        reachable_map[v.first][v.second] = d <= capacity[v.first][v.second];
        if (d >= capacity[v.first][v.second]) continue;
        for (int dir = 0; dir < DIRECTIONS; dir++) {
            point u = point(v.first + dy[dir], v.second + dx[dir]);
            if (0 <= u.first && u.first < size_n && 0 <= u.second && u.second < size_n && grid_map[u.first][u.second] != 'Y' && d + 1 < dist_map[u.first][u.second])
                dist_map[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void run_bfs(int sr, int sc, int d[][MAX_SIZE], int INF_VAL)
{
    fill((int*)d, (int*)d + MAX_SIZE * MAX_SIZE, INF_VAL);
    d[sr][sc] = 0;
    queue<point> q; q.push(point(sr, sc));
    while (!q.empty()) {
        point v = q.front(); int d_v = d[v.first][v.second]; q.pop();
        for (int dir = 0; dir < DIRECTIONS; dir++) {
            point u = point(v.first + dy[dir], v.second + dx[dir]);
            if (0 <= u.first && u.first < size_n && 0 <= u.second && u.second < size_n && grid_map[u.first][u.second] != 'Y' && d_v + 1 < d[u.first][u.second])
                d[u.first][u.second] = d_v + 1, q.push(u);
        }
    }
}

int max_flow()
{
    fill(flow_array, flow_array + total_vertices, 0); flow_array[0] = MAX_INF;
    priority_queue<point> pq; pq.push(point(MAX_INF, 0));
    while (!pq.empty()) {
        int v = pq.top().second, f = pq.top().first; pq.pop();
        if (flow_array[v] != f) continue;
        for (size_t i = 0; i < adjacency[v].size(); i++) {
            int u = adjacency[v][i];
            if (min(f, capacity[v][u]) > flow_array[u]) flow_array[u] = min(f, capacity[v][u]), parent_array[u] = v, pq.push(point(flow_array[u], u));
        }
    }
    int v = total_vertices - 1;
    if (flow_array[v] == 0) return 0;
    int total_flow = flow_array[v];
    while (v != 0) {
        int u = parent_array[v];
        capacity[u][v] -= total_flow; capacity[v][u] += total_flow;
        v = u;
    }
    return total_flow;
}

int main()
{
    scanf("%d %d", &size_n, &max_t);
    for (int i = 0; i < size_n; i++)
        for (int j = 0; j < size_n; j++) {
            scanf(" %c", &grid_map[i][j]);
            if (grid_map[i][j] == 'Z') { start_r = i; start_c = j; }
        }
    for (int i = 0; i < size_n; i++)
        for (int j = 0; j < size_n; j++)
            scanf(" %c", &backup_map[i][j]);
    first_bfs();
    total_vertices = 2 * size_n * size_n + 2;
    for (int i = 0; i < size_n; i++)
        for (int j = 0; j < size_n; j++) if (isdigit(grid_map[i][j]) && grid_map[i][j] > '0') {
            int v = i * size_n + j + 1; capacity[0][v] = grid_map[i][j] - '0'; adjacency[0].push_back(v); adjacency[v].push_back(0);
            second_bfs(i, j);
            for (int i2 = 0; i2 < size_n; i2++)
                for (int j2 = 0; j2 < size_n; j2++) if (reachable_map[i2][j2] && isdigit(backup_map[i2][j2]) && backup_map[i2][j2] > '0') {
                    int u = size_n * size_n + i2 * size_n + j2 + 1; capacity[v][u] = MAX_INF; adjacency[v].push_back(u); adjacency[u].push_back(v);
                }
        }
    for (int i = 0; i < size_n; i++)
        for (int j = 0; j < size_n; j++) if (isdigit(backup_map[i][j]) && backup_map[i][j] > '0') {
            int u = size_n * size_n + i * size_n + j + 1; capacity[u][total_vertices - 1] = backup_map[i][j] - '0'; adjacency[u].push_back(total_vertices - 1); adjacency[total_vertices - 1].push_back(u);
        }
    int flow;
    int total_flow_value = 0;
    while ((flow = max_flow()) != 0) total_flow_value += flow;
    printf("%d\n", total_flow_value);
    return 0;
}
